      "path": "mcp/src/server.ts",
      "content": "import { McpServer, type RegisteredTool } from \"@modelcontextprotocol/sdk/server/mcp.js\";\nimport { registerDatabaseTools } from \"./tools/databaseNoSQL.js\";\nimport { registerPGDatabaseTools } from \"./tools/databasePG.js\";\nimport { registerSQLDatabaseTools } from \"./tools/databaseSQL.js\";\nimport { registerEnvTools } from \"./tools/env.js\";\nimport { registerFunctionTools } from \"./tools/functions.js\";\nimport { registerHostingTools } from \"./tools/hosting.js\";\nimport { registerRagTools } from \"./tools/rag.js\";\nimport { registerSetupTools } from \"./tools/setup.js\";\nimport { registerPGStorageTools } from \"./tools/storagePG.js\";\nimport { registerStorageTools } from \"./tools/storage.js\";\n// import { registerMiniprogramTools } from \"./tools/miniprogram.js\";\nimport { SetLevelRequestSchema } from '@modelcontextprotocol/sdk/types.js';\nimport { registerCapiTools } from \"./tools/capi.js\";\nimport { registerCloudRunTools } from \"./tools/cloudrun.js\";\nimport { registerDeployTools } from \"./tools/deploy.js\";\nimport { registerDataModelTools } from \"./tools/dataModel.js\";\nimport { registerGatewayTools } from \"./tools/gateway.js\";\nimport { registerAgentTools } from \"./tools/agents.js\";\nimport { registerAppAuthTools } from \"./tools/app-auth.js\";\nimport { registerAppTools } from \"./tools/apps.js\";\nimport { registerLogTools } from \"./tools/logs.js\";\nimport { registerPermissionTools } from \"./tools/permissions.js\";\nimport { registerMsgPushTools } from \"./tools/msg-push.js\";\nimport { registerFeedbackTools } from \"./tools/feedback.js\";\nimport { CloudBaseOptions, Logger, PluginOptions } from \"./types.js\";\nimport type { AuthOptions } from \"./auth.js\";\nimport { isMessageKey, resolveInstanceLang, setInstanceLang, t, type Lang } from \"./i18n/index.js\";\nimport { localizeZodSchemaShape } from \"./i18n/schema.js\";\nimport { resolveServerInstructions } from \"./prompts/server-instructions.js\";\nimport { enableCloudMode } from \"./utils/cloud-mode.js\";\nimport { info } from './utils/logger.js';\nimport { resolveSiteAndRegion, SITE_REGION_MAP } from \"./utils/site-map.js\";\nimport { buildJsonToolResult, isToolPayloadError } from \"./utils/tool-result.js\";\nimport { wrapServerWithTelemetry, applyCategoryAnnotationMeta, type ToolAnnotations } from \"./utils/tool-wrapper.js\";\nimport {\n  normalizeClientName,\n  readClientCapabilitiesFromServer,\n  readMcpClientInfoFromServer,\n  reportToolkitSessionInitialized,\n} from \"./utils/telemetry.js\";\nimport { isMcpUiEnabled } from \"./utils/mcp-ui.js\";\nimport { registerGetStartedResource } from \"./resources/get-started.js\";\nimport { registerEnvCreditsResource } from \"./resources/env-credits.js\";\nimport { registerArtifactCardResource } from \"./resources/artifact-card.js\";\n\n// 插件定义\ninterface PluginDefinition {\n  name: string;\n  register: (server: ExtendedMcpServer) => void | Promise<void>;\n}\n\n// 默认插件列表\nconst DEFAULT_PLUGINS = [\n  \"env\",\n  \"database\",\n  \"pg_database\",\n  \"pg_storage\",\n  \"mysql_database\",\n  \"functions\",\n  \"hosting\",\n  \"storage\",\n  \"setup\",\n  \"rag\",\n  \"cloudrun\",\n  \"deploy\",\n  \"gateway\",\n  \"app-auth\",\n  \"apps\",\n  \"permissions\",\n  \"logs\",\n  \"agents\",\n  \"capi\",\n  \"feedback\",\n];\n\nfunction registerDatabase(server: ExtendedMcpServer) {\n  // NoSQL 数据库按站点能力集合注册（国际站默认不支持 NoSQL）\n  const { site } = resolveSiteAndRegion({\n    site: server.cloudBaseOptions?.site,\n    region: server.cloudBaseOptions?.region,\n  });\n  if (SITE_REGION_MAP[site].capabilities.noSql) {\n    registerDatabaseTools(server);\n  }\n  registerDataModelTools(server);\n}\n\nfunction registerMysqlDatabase(server: ExtendedMcpServer) {\n  registerSQLDatabaseTools(server);\n}\n\nfunction registerNoSQLDatabase(server: ExtendedMcpServer) {\n  const { site } = resolveSiteAndRegion({\n    site: server.cloudBaseOptions?.site,\n    region: server.cloudBaseOptions?.region,\n  });\n  if (SITE_REGION_MAP[site].capabilities.noSql) {\n    registerDatabaseTools(server);\n  }\n}\n\n// 可用插件映射\nconst AVAILABLE_PLUGINS: Record<string, PluginDefinition> = {\n  env: { name: \"env\", register: registerEnvTools },\n  database: { name: \"database\", register: registerDatabase },\n  mysql_database: { name: \"mysql_database\", register: registerMysqlDatabase },\n  pg_database: { name: \"pg_database\", register: registerPGDatabaseTools },\n  pg_storage: { name: \"pg_storage\", register: registerPGStorageTools },\n  \"database-nosql\": { name: \"database-nosql\", register: registerNoSQLDatabase },\n  \"database-sql\": { name: \"database-sql\", register: registerSQLDatabaseTools },\n  \"data-model\": { name: \"data-model\", register: registerDataModelTools },\n  functions: { name: \"functions\", register: registerFunctionTools },\n  hosting: { name: \"hosting\", register: registerHostingTools },\n  storage: { name: \"storage\", register: registerStorageTools },\n  setup: { name: \"setup\", register: registerSetupTools },\n  rag: { name: \"rag\", register: registerRagTools },\n  gateway: { name: \"gateway\", register: registerGatewayTools },\n  \"app-auth\": { name: \"app-auth\", register: registerAppAuthTools },\n  permissions: { name: \"permissions\", register: registerPermissionTools },\n  logs: { name: \"logs\", register: registerLogTools },\n  agents: { name: \"agents\", register: registerAgentTools },\n  apps: { name: \"apps\", register: registerAppTools },\n  cloudrun: { name: \"cloudrun\", register: registerCloudRunTools },\n  deploy: { name: \"deploy\", register: registerDeployTools },\n  capi: { name: \"capi\", register: registerCapiTools },\n  \"msg-push\": { name: \"msg-push\", register: registerMsgPushTools },\n  feedback: { name: \"feedback\", register: registerFeedbackTools },\n};\n\nconst PLUGIN_ALIASES: Record<string, string> = {\n  \"access-control\": \"permissions\",\n  \"auth-config\": \"app-auth\",\n  \"security-rule\": \"permissions\",\n  \"security-rules\": \"permissions\",\n  \"secret-rule\": \"permissions\",\n  \"secret-rules\": \"permissions\",\n  mysql: \"mysql_database\",\n  \"mysql-database\": \"mysql_database\",\n  \"sql-database\": \"mysql_database\",\n  users: \"permissions\",\n};\n\nfunction normalizePluginName(name: string): string {\n  const normalized = name.trim().toLowerCase().replace(/\\s+/g, \"-\");\n  return PLUGIN_ALIASES[normalized] ?? normalized;\n}\n\n/**\n * Parse enabled plugins list\n * @param pluginsEnabled Optional array of enabled plugin names (takes precedence over env var)\n * @param pluginsDisabled Optional array of disabled plugin names (merged with env var)\n * @returns Array of enabled plugin names\n */\nfunction parseEnabledPlugins(\n  pluginsEnabled?: string[],\n  pluginsDisabled?: string[]\n): string[] {\n  const enabledEnv = process.env.CLOUDBASE_MCP_PLUGINS_ENABLED;\n  const disabledEnv = process.env.CLOUDBASE_MCP_PLUGINS_DISABLED;\n\n  let enabledPlugins: string[];\n\n  // Priority: parameter > environment variable > default plugins\n  if (pluginsEnabled && pluginsEnabled.length > 0) {\n    enabledPlugins = pluginsEnabled;\n  } else if (enabledEnv) {\n    enabledPlugins = enabledEnv.split(\",\").map((p) => p.trim());\n  } else {\n    enabledPlugins = [...DEFAULT_PLUGINS];\n  }\n\n  const allDisabledPlugins = new Set<string>();\n\n  if (disabledEnv) {\n    disabledEnv\n      .split(\",\")\n      .map((p) => normalizePluginName(p))\n      .forEach((p) => allDisabledPlugins.add(p));\n  }\n\n  if (pluginsDisabled && pluginsDisabled.length > 0) {\n    pluginsDisabled\n      .map((p) => normalizePluginName(p))\n      .forEach((p) => allDisabledPlugins.add(p));\n  }\n\n  enabledPlugins = Array.from(\n    new Set(\n      enabledPlugins\n        .map((p) => normalizePluginName(p))\n        .filter((p) => !allDisabledPlugins.has(p)),\n    ),\n  );\n\n  return enabledPlugins;\n}\n\n/**\n * registerTool config with CloudBase `annotations.category` retained after\n * MCP SDK >=1.26 closed ToolAnnotations to strip unknown keys at the type level.\n */\nexport type CloudBaseRegisterToolConfig = {\n  title?: string;\n  description?: string;\n  inputSchema?: any;\n  outputSchema?: any;\n  annotations?: ToolAnnotations;\n  _meta?: Record<string, unknown>;\n};\n\n// Extend McpServer with CloudBase options and category-aware registerTool.\nexport interface ExtendedMcpServer extends McpServer {\n  cloudBaseOptions?: CloudBaseOptions;\n  authOptions?: AuthOptions;\n  /** 实例输出语言（zh/en）：description 注册选择 + 工具输出文案默认语言 */\n  lang?: Lang;\n  ide?: string;\n  /** MCP client 来源标识（hosted 场景由上游解析注入，如 cursor / claude-code） */\n  client?: string;\n  /**\n   * Metadata-only client identity used when this request has no handshake.\n   * `{ name, version }` only. Not a protocol object.\n   */\n  clientInfo?: { name: string; version?: string };\n  logger?: Logger;\n  enabledPlugins?: string[];\n  pluginOptions?: PluginOptions;\n  /** Registered tools for external hosts (e.g. WeChat IDE) to re-register. */\n  toolDefs: Array<{ name: string; description: string; inputSchema: any; handler: (input: any) => Promise<any> }>;\n\n  setLogger(logger: Logger): void;\n\n  /**\n   * Same as MCP SDK registerTool, but annotations may include CloudBase `category`.\n   * Handler typing stays intentionally loose to match existing tool call sites.\n   */\n  registerTool(\n    name: string,\n    config: CloudBaseRegisterToolConfig,\n    cb: (...args: any[]) => any,\n  ): RegisteredTool;\n}\n\n/**\n * 把工具 description / title 里写的词典 key 解析成实例语言的实际文案。\n * 非 key 的字符串（存量动态拼出来的 description）原样返回，保证向后兼容。\n */\nfunction resolveToolText(value: string, lang?: Lang): string {\n  return isMessageKey(value) ? t(value, undefined, lang) : value;\n}\n\n/**\n * Create and configure a CloudBase MCP Server instance\n * @param options Server configuration options\n * @returns Configured McpServer instance\n *\n * @example\n * import { createCloudBaseMcpServer } from \"@cloudbase/mcp-server\";\n * import { StdioServerTransport } from \"@modelcontextprotocol/sdk/server/stdio.js\";\n *\n * const server = createCloudBaseMcpServer({ cloudBaseOptions: {\n *  envId,    // 环境ID\n *  secretId,  // 腾讯云密钥ID\n *  secretKey, // 腾讯云密钥\n *  region, // 地域，默认是 ap-shanghai\n *  token // 临时密钥，有有效期限制，生成密钥时可控制\n * } });\n *\n * const transport = new StdioServerTransport();\n * await server.connect(transport);\n */\nexport async function createCloudBaseMcpServer(options?: {\n  name?: string;\n  version?: string;\n  enableTelemetry?: boolean;\n  cloudBaseOptions?: CloudBaseOptions;\n  authOptions?: AuthOptions;\n  cloudMode?: boolean;\n  ide?: string;\n  client?: string;\n  /**\n   * Client name/version to report when the MCP handshake clientInfo is empty.\n   * Metadata only. Hosted requests pass the value remembered for this credential.\n   */\n  clientInfo?: { name: string; version?: string };\n  /**\n   * 会话标识的取值入口（**调用点注入**，可选）。\n   *\n   * 有状态 HTTP / 托管路径把当前 transport 的 `sessionId` 传进来（那是公开 getter）；\n   * stdio、以及无状态托管（`sessionIdGenerator: undefined`）没有会话概念 ⇒ **不注入**，\n   * 会话级上报回落到常量，等价于\"这个实例就是一个会话\"。\n   * 只有会话级遥测用得到它；不注入时行为与\"每实例一条\"完全一致。\n   */\n  getSessionId?: () => string | undefined;\n  logger?: Logger;\n  pluginsEnabled?: string[];\n  pluginsDisabled?: string[];\n  pluginOptions?: PluginOptions;\n  /**\n   * 实例输出语言（zh/en）。解析链：本参数 > TCB_LANG 环境变量\n   * > `.cloudbase/project.json` 的 lang > 默认 zh。\n   * 影响：工具 description / title 里的词典 key 按本语言解析 + 工具输出文案默认语言。\n   */\n  lang?: Lang | string;\n}): Promise<ExtendedMcpServer> {\n  const {\n    name = \"cloudbase-mcp\",\n    version = \"1.0.0\",\n    enableTelemetry = true,\n    cloudBaseOptions,\n    authOptions,\n    cloudMode = false,\n    ide,\n    client,\n    clientInfo,\n    getSessionId,\n    logger,\n    pluginsEnabled,\n    pluginsDisabled,\n    pluginOptions,\n    lang,\n  } = options ?? {};\n\n  // Enable cloud mode if specified\n  if (cloudMode) {\n    enableCloudMode();\n  }\n\n  // Create server instance\n  // 实例语言必须在构造前解析：`instructions` 是 initialize 的返回字段，构造时就得定稿，\n  // 不能像工具 description 那样等注册包装层再按 lang 改写。\n  const instanceLang = resolveInstanceLang(lang);\n  const server = new McpServer(\n    {\n      name,\n      version,\n    },\n    {\n      capabilities: {\n        tools: {},\n        // MCP Apps 扩展声明：服务端按通用扩展机制用**空对象**（无 settings）。\n        // 注意不手写 `resources`——`registerResource` 会自己在 connect 前带上能力位。\n        extensions: { \"io.modelcontextprotocol/ui\": {} },\n        ...(ide === \"CodeBuddy\" ? { logging: {} } : {}),\n      },\n      // 免协商的「怎么用我」自述：不占 tools/list 的上下文，客户端不支持时自然忽略。\n      instructions: resolveServerInstructions(instanceLang),\n    },\n  ) as ExtendedMcpServer;\n\n  // 初始化 toolDefs，用于外部提取工具列表（如微信 IDE）\n  server.toolDefs = [];\n\n  // 实例语言解析（须在工具注册前完成：registerTool 包装层按 lang 解析词典 key 形式的 description）\n  server.lang = instanceLang;\n  // 同步到 i18n 模块级 instanceLang：否则 t() 无 langOverride 时会退化成\n  // TCB_LANG/project.json/zh，导致 options.lang 只影响工具 description、不影响工具输出文案。\n  setInstanceLang(server.lang);\n\n  const originalRegisterTool = server.registerTool.bind(server);\n  server.registerTool = ((name: string, meta: any, handler: (args: any) => Promise<any>) => {\n    const toolMeta = applyCategoryAnnotationMeta(meta ?? {});\n    // 国际化描述支持：description/title 写成词典 key 字符串（如 \"storage.queryDescription\"）时\n    // 按实例 lang 解析为实际文案；普通字符串（存量动态 description）原样透传，工具侧零改动。\n    if (typeof toolMeta?.description === \"string\") {\n      toolMeta.description = resolveToolText(toolMeta.description, server.lang);\n    }\n    if (typeof toolMeta?.title === \"string\") {\n      toolMeta.title = resolveToolText(toolMeta.title, server.lang);\n    }\n    if (toolMeta?.inputSchema && typeof toolMeta.inputSchema === \"object\") {\n      toolMeta.inputSchema = localizeZodSchemaShape(toolMeta.inputSchema, server.lang);\n    }\n    if (toolMeta?.outputSchema && typeof toolMeta.outputSchema === \"object\") {\n      toolMeta.outputSchema = localizeZodSchemaShape(toolMeta.outputSchema, server.lang);\n    }\n    // 同步记录到 toolDefs\n    server.toolDefs.push({\n      name,\n      description: toolMeta?.description ?? toolMeta?.title ?? '',\n      inputSchema: toolMeta?.inputSchema ?? {},\n      handler,\n    });\n    return originalRegisterTool(name, toolMeta, async (args: any) => {\n      try {\n        return await handler(args);\n      } catch (error) {\n        if (isToolPayloadError(error)) {\n          // 在结构化错误返回中注入 MCP 版本号\n          const payload = { ...error.payload, mcpVersion: version };\n          return buildJsonToolResult(payload);\n        }\n        throw error;\n      }\n    });\n  }) as typeof server.registerTool;\n\n  // Only set logging handler if logging capability is declared\n  if (ide === \"CodeBuddy\") {\n    server.server.setRequestHandler(SetLevelRequestSchema, (request, extra) => {\n      info(`--- Logging level: ${request.params.level}`);\n      return {};\n    });\n  }\n\n  // Store cloudBaseOptions in server instance for tools to access\n  if (cloudBaseOptions) {\n    server.cloudBaseOptions = cloudBaseOptions;\n  }\n\n  if (authOptions) {\n    server.authOptions = authOptions;\n  }\n\n  // Store pluginOptions in server instance for plugins to access\n  if (pluginOptions) {\n    server.pluginOptions = pluginOptions;\n  }\n\n  // Store ide in server instance for telemetry\n  if (ide) {\n    server.ide = ide;\n  }\n\n  // Store client in server instance for telemetry (normalized, invalid values dropped)\n  const normalizedClient = normalizeClientName(client);\n  if (normalizedClient) {\n    server.client = normalizedClient;\n  }\n\n  const hintedName = typeof clientInfo?.name === \"string\" ? clientInfo.name.trim() : \"\";\n  if (hintedName) {\n    const hintedVersion = typeof clientInfo?.version === \"string\" ? clientInfo.version.trim() : \"\";\n    server.clientInfo = hintedVersion\n      ? { name: hintedName, version: hintedVersion }\n      : { name: hintedName };\n  }\n\n  // Store logger in server instance for tools to access\n  if (logger) {\n    server.logger = logger;\n  }\n\n  server.setLogger = (logger: Logger) => {\n    server.logger = logger;\n  }\n\n  // Enable telemetry if requested\n  if (enableTelemetry) {\n    wrapServerWithTelemetry(server);\n\n    // 会话建立后上报一次（补\"分母\"：进程 start 早于握手，拿不到 client 与能力声明）。\n    // **这一个 if 就是总闸**：`enableTelemetry: false` 时连这条会话事件也不发——\n    // 关掉遥测的调用方（测试环境分支、冒烟脚本、评审 harness）本来就是为了不出网。\n    // - **每会话只发一次**：幂等粒度是**会话**，不是 server 实例 —— 同一会话里重复的\n    //   initialized 通知只报一次；不同会话即使共用同一个实例也各报一次；\n    // - **fire-and-forget**：绝不 await、也不让上报失败冒泡到握手；\n    // - 字段拿不到就留空，不臆造（见 reportToolkitSessionInitialized 的注释）。\n    // 多会话同进程的场景（HTTP/托管路径的每会话回调）本期不接，留待后续。\n    //\n    // 会话身份的取值来源（不留含糊）：**由调用点注入的 `getSessionId()`**\n    //   - 有状态 HTTP / 托管路径：`hosted/handle-hosted-mcp-request.ts:154` 注入\n    //     `() => transport?.sessionId`（transport 在 `:134` 声明、`:164` 创建、`:171` connect，\n    //     与建 server（`:142`）同一作用域）；`StreamableHTTPServerTransport.sessionId` 是**公开 getter**；\n    //   - stdio（`cli.ts`）与**无状态**托管（`sessionIdGenerator: undefined`，`:165`）没有会话概念\n    //     ⇒ 不注入 ⇒ 回落到常量 `single-session`，等价于\"这个实例就是一个会话\"。\n    // 不读 SDK 的 `Protocol._transport`（那是私有的指针，本版也没有公开的 transport 访问器）。\n    //\n    // 为什么粒度是会话而不是实例：今天托管路径每个请求都新建实例（无缓存 Map），两种粒度等价；\n    // 一旦有人把实例按凭证缓存复用，\"实例级幂等\"就会让 N 个会话只报 1 条、分母漏计 N−1。\n    //\n    // 内存：这个 Set 只增不减。托管路径每请求一个实例、随请求消亡；被复用的长命实例则会按\n    // 会话数累积（每个键就是一个 sessionId 字符串）。要收紧得挂在 transport 的关闭钩子上，\n    // 但 `onclose` 由 SDK 的协议层持有（`shared/protocol.js:221`），这里不为它绕路 —— 记为后续项。\n    const reportedSessions = new Set<string>();\n    const currentSessionKey = (): string => {\n      let injected: string | undefined;\n      try {\n        injected = getSessionId?.();\n      } catch {\n        // 注入的取值抛错不该影响会话：按\"没有会话标识\"处理（回落常量）\n      }\n      return typeof injected === \"string\" && injected.length > 0 ? injected : \"single-session\";\n    };\n    server.server.oninitialized = () => {\n      const sessionKey = currentSessionKey();\n      if (reportedSessions.has(sessionKey)) {\n        return;\n      }\n      reportedSessions.add(sessionKey);\n      void reportToolkitSessionInitialized({\n        cloudBaseOptions,\n        ide: server.ide || process.env.INTEGRATION_IDE,\n        client: server.client || process.env.CLOUDBASE_MCP_CLIENT,\n        mcpClientInfo: readMcpClientInfoFromServer(server),\n        mcpClientCapabilities: readClientCapabilitiesFromServer(server),\n      }).catch(() => {\n        /* 遥测失败不影响会话 */\n      });\n    };\n  }\n\n  // Register plugins based on configuration\n  const enabledPlugins = parseEnabledPlugins(pluginsEnabled, pluginsDisabled);\n  server.enabledPlugins = enabledPlugins;\n\n  for (const pluginName of enabledPlugins) {\n    const plugin = AVAILABLE_PLUGINS[pluginName];\n    if (plugin) {\n      await plugin.register(server);\n    }\n  }\n\n  // MCP Apps 三张卡（get-started / env-credits / artifact-card）。与工具同生命周期、一次性注册；\n  // 必须在 connect 前完成，否则 registerCapabilities 会抛错。resources/list 仍为空。\n  // CLOUDBASE_MCP_UI=off 时整块跳过：工具也不再带 `_meta.ui`，宿主不会为卡片留位置。\n  if (isMcpUiEnabled()) {\n    registerGetStartedResource(server);\n\n    // 环境资源用量面板：只读用量与套餐，不执行计费（引导交给会话里的技能）。\n    registerEnvCreditsResource(server);\n\n    // 产物卡片：挂在三个部署类工具上，只读展示部署状态与访问地址，写意图一律交给会话。\n    registerArtifactCardResource(server);\n  }\n\n  return server;\n}\n\n/**\n * Get the default configured CloudBase MCP Server\n */\nexport function getDefaultServer(): Promise<ExtendedMcpServer> {\n  return createCloudBaseMcpServer();\n}\n\n// Re-export types and utilities that might be useful\nexport type { McpServer } from \"@modelcontextprotocol/sdk/server/mcp.js\";\nexport { StdioServerTransport } from \"@modelcontextprotocol/sdk/server/stdio.js\";\nexport { error, info, warn } from \"./utils/logger.js\";\nexport {\n  reportToolCall,\n  reportToolkitLifecycle,\n  telemetryReporter,\n  normalizeClientName\n} from \"./utils/telemetry.js\";\n"
    },
    {
      "path": "mcp/src/utils/tool-wrapper.ts",
      "content": "import { McpServer } from \"@modelcontextprotocol/sdk/server/mcp.js\";\nimport type { ToolAnnotations as SdkToolAnnotations } from \"@modelcontextprotocol/sdk/types.js\";\nimport { getCachedEnvId } from '../cloudbase-manager.js';\nimport { ExtendedMcpServer } from \"../server.js\";\nimport { shouldRegisterTool } from './cloud-mode.js';\nimport { debug } from './logger.js';\nimport { reportToolCall, readMcpClientInfoFromServer, readClientCapabilitiesFromServer } from './telemetry.js';\nimport { isBusinessFailureToolResult, isToolPayloadError, ToolPayloadError, withBusinessFailureIsError } from \"./tool-result.js\";\nimport { applyRepeatGuardToPayload, resetRepeatGuard } from \"./repeat-error-guard.js\";\nimport { enhanceErrorMessage, resolveRequestId } from \"./error-guidance.js\";\nimport { resolveSiteAndRegion } from \"./site-map.js\";\nimport { guardDestructiveAction, type ConfirmationServer } from \"./confirmation-guard.js\";\nimport { guardCredentialWrite, type CredentialGuardServer } from \"./credential-guard.js\";\n\n\n/**\n * 工具包装器，为 MCP 工具添加数据上报功能\n * 自动记录工具调用的成功/失败状态、执行时长等信息\n */\n\n// Re-export MCP SDK Tool type for other modules.\nexport type { Tool } from \"@modelcontextprotocol/sdk/types.js\";\n\n/**\n * CloudBase extends MCP ToolAnnotations with a stable `category` hint used by\n * IDE UIs for grouping. SDK >=1.26 types annotations as a closed/strip object,\n * so we keep category via an intersection while still passing it through at\n * runtime (listTools returns registered annotations without schema stripping).\n */\nexport type ToolAnnotations = SdkToolAnnotations & {\n  category?: string;\n};\n\ntype ToolConfigWithCategory = {\n  annotations?: ToolAnnotations;\n  _meta?: Record<string, unknown>;\n  [key: string]: unknown;\n};\n\n/**\n * Mirror annotations.category into _meta.category.\n *\n * MCP SDK Client >=1.26 parses tools/list with a stripping ToolAnnotationsSchema,\n * which drops unknown annotation keys. `_meta` remains available to clients, while\n * the server wire payload still includes annotations.category for non-SDK hosts.\n */\nexport function applyCategoryAnnotationMeta<T extends ToolConfigWithCategory>(config: T): T {\n  const category = config?.annotations?.category;\n  if (typeof category !== \"string\" || category.length === 0) {\n    return config;\n  }\n\n  const existingMeta =\n    config._meta && typeof config._meta === \"object\" ? config._meta : undefined;\n\n  if (existingMeta && existingMeta.category === category) {\n    return config;\n  }\n\n  return {\n    ...config,\n    _meta: {\n      ...existingMeta,\n      category,\n    },\n  };\n}\n\n// 构建时注入的版本号\ndeclare const __MCP_VERSION__: string;\n\nconst GITHUB_REPO = \"https://github.com/TencentCloudBase/CloudBase-AI-ToolKit\";\nconst CNB_REPO = \"https://cnb.cool/tencent/cloud/cloudbase/CloudBase-AI-ToolKit\";\n/** 云平台 / 权限 / 账号类问题统一去社区仓库，不收在本仓 issue 里 */\nconst CNB_COMMUNITY_ISSUES = \"https://cnb.cool/tencent/cloud/cloudbase/community/-/issues/new\";\n\n/**\n * Point toolkit bugs at a pull request and platform problems at the community issue tracker.\n * The URL carries no environment ID, arguments, or error text.\n */\nfunction contributionHint(server: ExtendedMcpServer): string {\n    const site = resolveSiteAndRegion({\n        site: server.cloudBaseOptions?.site,\n        region: server.cloudBaseOptions?.region,\n    }).site;\n    if (site === \"intl\") {\n        return [\n            \"If this is a bug in this repo's MCP server, skills, or CLI, open a pull request:\",\n            `${GITHUB_REPO}/blob/main/CONTRIBUTING.md`,\n            \"If it is the cloud platform, permissions, or the account, open an issue and fill it in yourself. Do not include the environment ID or secrets:\",\n            `${GITHUB_REPO}/issues/new`,\n        ].join(\"\\n\");\n    }\n    return [\n        \"如果问题出在本仓库的 MCP、skill 或 CLI，请按贡献指南提 Pull Request：\",\n        `${CNB_REPO}/-/blob/main/CONTRIBUTING.md`,\n        \"如果是云平台、权限或账号问题，请打开 issue 页面自行填写。不要把环境 ID 或密钥写进去：\",\n        CNB_COMMUNITY_ISSUES,\n    ].join(\"\\n\");\n}\n\n/**\n * 创建包装后的处理函数，添加数据上报功能\n */\n/**\n * 工具自己返回的失败：结构化 `{ success: false }`（`isBusinessFailureToolResult` 已覆盖\n * 顶层 / structuredContent / JSON 文本三种挂法），**或**已经显式带 `isError: true` 的回执。\n * 护栏拦截的返回两样都不占（它的载荷是 `{status, executed:false}`）。\n */\nfunction isReturnedFailureResult(result: unknown): boolean {\n    if (!result || typeof result !== 'object') {\n        return false;\n    }\n    if ((result as Record<string, unknown>).isError === true) {\n        return true;\n    }\n    return isBusinessFailureToolResult(result);\n}\n\n/**\n * 失败时给客户端的最终文案：**抛错与\"返回的失败\"共用这一处构造**，\n * 所以两条路径对同一个底层错误得到的文本逐字相同（🆔 RequestId + 📦 版本页脚都在这里）。\n */\nfunction buildFailureClientText(\n    errorMessage: string,\n    requestId: string | undefined,\n    server: ExtendedMcpServer,\n): string {\n    const mcpVersion = typeof __MCP_VERSION__ !== 'undefined' ? __MCP_VERSION__ : 'unknown';\n    const requestIdSuffix = requestId ? `\\n🆔 RequestId: ${requestId}` : '';\n    return `${errorMessage}${requestIdSuffix}\\n\\n📦 CloudBase MCP v${mcpVersion}\\n${contributionHint(server)}`;\n}\n\n/** 从工具返回的失败结果里取\"人话那句\"+ 结构化错误码（用于指引匹配）。 */\nfunction failureMessageOf(result: unknown): { message: string; code?: string; parsed?: Record<string, unknown>; text?: string } {\n    const content = Array.isArray((result as any)?.content) ? (result as any).content : [];\n    const firstText = content.find(\n        (item: any) => item && item.type === 'text' && typeof item.text === 'string',\n    );\n    const text: string | undefined = firstText?.text;\n    if (typeof text === 'string') {\n        try {\n            const parsed = JSON.parse(text);\n            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {\n                const record = parsed as Record<string, unknown>;\n                const message =\n                    typeof record.message === 'string' && record.message\n                        ? record.message\n                        : typeof record.error === 'string' && record.error\n                            ? record.error\n                            : text;\n                const code =\n                    typeof record.code === 'string' ? record.code\n                        : typeof record.errorCode === 'string' ? record.errorCode\n                            : undefined;\n                return { message, code, parsed: record, text };\n            }\n        } catch {\n            // 纯文本失败回执（buildTextErrorResult）：整段就是那句话\n        }\n        return { message: text, text };\n    }\n    const record = (result ?? {}) as Record<string, unknown>;\n    const message =\n        typeof record.message === 'string' && record.message ? record.message : '工具返回了失败结果';\n    return { message, code: typeof record.code === 'string' ? record.code : undefined };\n}\n\n/**\n * 把\"返回的失败\"改成与抛错同款的文案：文案本体走 `enhanceErrorMessage`（同一张指引表），\n * 尾部接同一个 RequestId/版本页脚。**结构化契约不破**：\n *   - 文本内容是 JSON 对象 ⇒ 只替换它的 `message` 字段，其余字段原样保留、仍可 JSON.parse；\n *   - 纯文本失败回执 ⇒ 整段替换（与抛错路径逐字相同）。\n */\nfunction withEnhancedFailureText(\n    result: any,\n    errorMessage: string,\n    requestId: string | undefined,\n    server: ExtendedMcpServer,\n): any {\n    const clientText = buildFailureClientText(errorMessage, requestId, server);\n    const info = failureMessageOf(result);\n    const content = Array.isArray(result?.content) ? result.content : [];\n    const index = content.findIndex(\n        (item: any) => item && item.type === 'text' && typeof item.text === 'string',\n    );\n\n    if (info.parsed && index >= 0) {\n        const nextContent = [...content];\n        nextContent[index] = {\n            ...nextContent[index],\n            text: JSON.stringify({ ...info.parsed, message: clientText }, null, 2),\n        };\n        return { ...result, content: nextContent };\n    }\n    if (typeof info.text === 'string' && index >= 0) {\n        const nextContent = [...content];\n        nextContent[index] = { ...nextContent[index], text: clientText };\n        return { ...result, content: nextContent };\n    }\n    return result;\n}\n\nfunction createWrappedHandler(name: string, handler: any, server: ExtendedMcpServer) {\n    return async (args: any, extra?: { requestId?: unknown; signal?: unknown }) => {\n        const startTime = Date.now();\n        let success = false;\n        let errorMessage: string | undefined;\n        let requestId: string | undefined;\n\n        try {\n            debug(`开始执行工具: ${name}`, { args: sanitizeArgs(args) });\n            // In test environment, skip logger to avoid potential blocking\n            const isTestEnvironment =\n              process.env.NODE_ENV === \"test\" || process.env.VITEST === \"true\";\n            if (!isTestEnvironment) {\n                server.logger?.({ type: 'beforeToolCall', toolName: name, args: sanitizeArgs(args) });\n            }\n\n            // 凭证形态入参的执行前**软确认**（先于破坏性确认）。参数里扫到凭证形态字符串时，\n            // 要求客户端拿这串与它自己那份原始来源比对确认；未通过则不执行，直接返回说明文本。\n            // 与破坏性确认同一取舍：这是\"正常返回\"而不是错误（详见 credential-guard.ts）。\n            const credentialDecision = await guardCredentialWrite(server as unknown as CredentialGuardServer, {\n                toolName: name,\n                args,\n                extra: extra as { requestId?: any },\n            });\n            if (credentialDecision.intercept) {\n                success = true;\n                return credentialDecision.result;\n            }\n\n            // 破坏性动作的执行前确认（护栏）。命中且未确认时不执行，直接返回说明文本：\n            // 这是\"正常返回\"而不是错误（详见 confirmation-guard.ts 的取舍说明）。\n            const guardDecision = await guardDestructiveAction(server as unknown as ConfirmationServer, {\n                toolName: name,\n                args,\n                extra: extra as { requestId?: any },\n            });\n            if (guardDecision.intercept) {\n                success = true;\n                return guardDecision.result;\n            }\n\n            // 执行原始处理函数（extra 一并透传，工具可据此拿到在途请求 id）\n            const result = await handler(args, extra);\n\n            // 工具**自己返回**的失败（`{ success: false }` 结构化载荷，或已经带 `isError: true` 的\n            // 失败回执）与\"抛错\"是同一件事：遥测要按失败记，文案要吃同一套收尾（增强 + RequestId +\n            // 版本页脚）。护栏拦截的返回走不到这里——它在上面就 return 了，且它的载荷既没有\n            // `success: false` 也没有 `isError`（见 confirmation-guard.ts / credential-guard.ts）：\n            // 那是\"用户选择不执行\"，不是失败。\n            const returnedFailure = isReturnedFailureResult(result);\n            success = !returnedFailure;\n            // 同一凭证的工具成功说明重复错误循环已被打破，只清零该凭证的计数\n            if (!returnedFailure) {\n                resetRepeatGuard(server);\n            }\n            requestId = extractRequestIdFromToolResult(result);\n            const duration = Date.now() - startTime;\n            debug(returnedFailure ? `工具返回失败结果: ${name}` : `工具执行成功: ${name}`, {\n                duration,\n                requestId: requestId || undefined,\n            });\n            if (!isTestEnvironment) {\n                server.logger?.({\n                    type: returnedFailure ? 'errorToolCall' : 'afterToolCall',\n                    toolName: name,\n                    args: sanitizeArgs(args),\n                    ...(returnedFailure ? { message: failureMessageOf(result).message } : { result }),\n                    duration,\n                });\n            }\n            if (returnedFailure && !isTestEnvironment) {\n                const failure = failureMessageOf(result);\n                errorMessage = enhanceErrorMessage(\n                    { message: failure.message, ...(failure.code ? { code: failure.code } : {}) },\n                    failure.message,\n                );\n                return withBusinessFailureIsError(\n                    withEnhancedFailureText(result, errorMessage, requestId, server),\n                );\n            }\n            // 业务失败（结构化 { success: false } 返回）必须带 MCP isError=true，\n            // 否则客户端会把失败误判为成功（实测 applyMigration / 知识库查询失败均踩坑）。\n            return withBusinessFailureIsError(result);\n        } catch (error) {\n            success = false;\n            // 在这里统一挂错误指引，而不是每个工具各自 catch 里做一次：\n            // 全部工具的失败都会经过这一处，新增指引只需往注册表里加一条。\n            errorMessage = enhanceErrorMessage(\n              error,\n              error instanceof Error ? error.message : String(error),\n            );\n            requestId = resolveRequestId(error);\n            debug(`工具执行失败: ${name}`, {\n                error: errorMessage,\n                requestId: requestId || undefined,\n                duration: Date.now() - startTime\n            });\n            const isTestEnvironment =\n              process.env.NODE_ENV === \"test\" || process.env.VITEST === \"true\";\n            if (!isTestEnvironment) {\n                server.logger?.({ type: 'errorToolCall', toolName: name, args: sanitizeArgs(args), message: errorMessage, duration: Date.now() - startTime });\n            }\n\n            // Preserve structured tool guidance such as next_step.\n            // These errors are expected control flow and should be serialized by the outer server wrapper.\n            if (isToolPayloadError(error)) {\n                // 连续相同结构化错误达到阈值时注入 repeat_guard 升级提示，\n                // 打断无头客户端的原样重试循环（不改写 message，保持遥测聚合稳定）\n                const payload = applyRepeatGuardToPayload(error.payload, server);\n                throw new ToolPayloadError(payload);\n            }\n\n            // In tests, avoid any extra work that may block (envId lookup, issue link generation, etc.)\n            if (isTestEnvironment) {\n                throw error instanceof Error ? error : new Error(String(error));\n            }\n\n            const enhancedErrorMessage = buildFailureClientText(errorMessage, requestId, server);\n\n            // 创建新的错误对象，保持原有的错误类型但更新消息\n            const enhancedError = error instanceof Error\n                ? new Error(enhancedErrorMessage)\n                : new Error(enhancedErrorMessage);\n\n            // 保持原有的错误属性\n            if (error instanceof Error) {\n                enhancedError.stack = error.stack;\n                enhancedError.name = error.name;\n            }\n\n            // 重新抛出增强的错误\n            throw enhancedError;\n        } finally {\n            // 上报工具调用数据（测试环境中跳过，避免阻塞）\n            const isTestEnvironment =\n              process.env.NODE_ENV === \"test\" || process.env.VITEST === \"true\";\n            \n            if (!isTestEnvironment) {\n                const duration = Date.now() - startTime;\n                \n                // 如果 server.cloudBaseOptions 为空或没有 envId，尝试从缓存获取并更新\n                let cloudBaseOptions = server.cloudBaseOptions;\n                if (!cloudBaseOptions?.envId) {\n                    const cachedEnvId = getCachedEnvId();\n                    if (cachedEnvId) {\n                        cloudBaseOptions = { ...cloudBaseOptions, envId: cachedEnvId };\n                    }\n                }\n                \n                // 异步上报，不阻塞工具返回\n                reportToolCall({\n                    toolName: name,\n                    success,\n                    requestId,\n                    duration,\n                    error: errorMessage,\n                    inputParams: sanitizeArgs(args), // 添加入参上报\n                    action: args?.action, // 工具级 action（如 auth 的 status/set_env）\n                    cloudBaseOptions: cloudBaseOptions, // 传递 CloudBase 配置（可能已更新）\n                    ide: server.ide || process.env.INTEGRATION_IDE, // 传递集成IDE信息\n                    client: server.client || process.env.CLOUDBASE_MCP_CLIENT, // 传递 MCP client 来源标识\n                    mcpClientInfo: readMcpClientInfoFromServer(server),\n                    mcpClientCapabilities: readClientCapabilitiesFromServer(server),\n                }).catch(err => {\n                    // 静默处理上报错误，不影响主要功能\n                    debug('遥测上报失败', { toolName: name, error: err instanceof Error ? err.message : String(err) });\n                });\n            }\n        }\n    };\n}\n\nfunction extractRequestIdFromToolResult(result: any): string | undefined {\n    if (!result || typeof result !== 'object') {\n        return undefined;\n    }\n\n    if (typeof result.requestId === 'string' && result.requestId.length > 0) {\n        return result.requestId;\n    }\n\n    if (typeof result.RequestId === 'string' && result.RequestId.length > 0) {\n        return result.RequestId;\n    }\n\n    const content = Array.isArray((result as any).content) ? (result as any).content : [];\n    for (const item of content) {\n        if (!item || item.type !== 'text' || typeof item.text !== 'string') {\n            continue;\n        }\n\n        try {\n            const parsed = JSON.parse(item.text);\n            if (parsed && typeof parsed === 'object') {\n                if (typeof parsed.requestId === 'string' && parsed.requestId.length > 0) {\n                    return parsed.requestId;\n                }\n                if (typeof parsed.RequestId === 'string' && parsed.RequestId.length > 0) {\n                    return parsed.RequestId;\n                }\n            }\n        } catch {\n            // Ignore non-JSON text payloads.\n        }\n    }\n\n    return undefined;\n}\n\n/**\n * 包装 MCP Server 的 registerTool 方法，添加数据上报功能和条件注册\n * @param server MCP Server 实例\n */\nexport function wrapServerWithTelemetry(server: McpServer): void {\n    // 保存原始的 registerTool 方法\n    const originalRegisterTool = server.registerTool.bind(server);\n\n    // Override the registerTool method to add telemetry and conditional registration\n    server.registerTool = function (toolName: string, toolConfig: any, handler: any) {\n        // If the tool should not be registered in the current mode, do not register and return undefined\n        if (!shouldRegisterTool(toolName)) {\n            debug(`Cloud mode: skipping registration of incompatible tool: ${toolName}`);\n            // Explicitly return undefined to satisfy the expected type\n            return undefined as any;\n        }\n\n        // Use the wrapped handler, passing the server instance\n        const wrappedHandler = createWrappedHandler(toolName, handler, server as unknown as ExtendedMcpServer);\n\n        // Call the original registerTool method\n        return originalRegisterTool(toolName, applyCategoryAnnotationMeta(toolConfig ?? {}), wrappedHandler);\n    };\n}\n\n/**\n * 清理参数中的敏感信息，用于日志记录\n * @param args 原始参数\n * @returns 清理后的参数\n */\nfunction sanitizeArgs(args: any): any {\n    if (!args || typeof args !== 'object') {\n        return args;\n    }\n\n    const sanitized = { ...args };\n\n    // 敏感字段列表\n    const sensitiveFields = [\n        'password', 'token', 'secret', 'key', 'auth',\n        'localPath', 'filePath', 'content', 'code',\n        'secretId', 'secretKey', 'envId'\n    ];\n\n    // 递归清理敏感字段\n    function cleanObject(obj: any): any {\n        if (Array.isArray(obj)) {\n            return obj.map(cleanObject);\n        }\n\n        if (obj && typeof obj === 'object') {\n            const cleaned: any = {};\n            for (const [key, value] of Object.entries(obj)) {\n                const lowerKey = key.toLowerCase();\n                const isSensitive = sensitiveFields.some(field => lowerKey.includes(field));\n\n                if (isSensitive) {\n                    cleaned[key] = '[REDACTED]';\n                } else {\n                    cleaned[key] = cleanObject(value);\n                }\n            }\n            return cleaned;\n        }\n\n        return obj;\n    }\n\n    return cleanObject(sanitized);\n}\n"
    },
    {
      "path": "mcp/src/utils/confirmation-guard.ts",
      "content": "import type { RequestId } from \"@modelcontextprotocol/sdk/types.js\";\nimport { getCachedEnvId } from \"../cloudbase-manager.js\";\nimport { t } from \"../i18n/index.js\";\nimport { isFormElicitationSupported, requestChoiceElicitation } from \"./elicitation.js\";\nimport { destructiveConfirmationKeys, resolveDestructiveAction } from \"./destructive-actions.js\";\nimport { debug } from \"./logger.js\";\nimport { isSkippedByList, parseSkipList } from \"./skip-list.js\";\n\n/**\n * 破坏性动作的**执行前确认**（护栏，不是安全边界）。\n *\n * 定位：让一次不可逆的删除，在执行前变成一次看得见的选择。三条设计取舍：\n *\n *   1. **客户端没声明 form 能力 ⇒ 不弹、照常执行**（不阻塞、不降级成聊天里的二次询问）。\n *   2. **客户端自行应答（< 500ms）不算「人的决定」**：用户把客户端设成完全访问/不询问，本身就是在说\n *      \"别问我\"，拦住他等于替他做决定。这类应答按\"未询问\"放行，可用\n *      `CLOUDBASE_MCP_ELICIT_AUTO_APPROVE=block` 反过来拦下。判据是耗时，不是 `action` 的值。\n *   3. **被拦下时返回正常结果**（`isError` 不置位、`structuredContent` 里不放 `success`）：\n *      标成失败会让客户端渲染成出错、模型可能自动重试同一个删除。注意包装层会把\n *      `structuredContent.success === false` 自动标成 MCP 错误（见 tool-result.ts），所以这里不能带 `success`。\n *\n * 首次接线点：`tool-wrapper.ts` 的 `createWrappedHandler`（全部工具的唯一必经之路）。\n */\n\n/** 确认窗口：必须窄于客户端的请求超时（60s），否则窗口会先被客户端关掉 */\nexport const CONFIRMATION_TIMEOUT_MS = 45_000;\n\n/** 客户端自行应答的临界值。实测：客户端自行应答 0~2ms，人读完文案点按钮约 1s 以上 */\nexport const AUTO_ANSWER_THRESHOLD_MS = 500;\n\n/** 逗号分隔的跳过清单：可写 `工具名` 或 `工具名.action`，区分大小写，无通配 */\nexport const SKIP_ENV_NAME = \"CLOUDBASE_MCP_SKIP_ELICITATIONS\";\n\n/** 客户端自行应答时是否放行：`allow`（默认）/ `block` */\nexport const AUTO_APPROVE_ENV_NAME = \"CLOUDBASE_MCP_ELICIT_AUTO_APPROVE\";\n\nexport type ConfirmationStatus =\n    | \"not_applicable\"\n    | \"accepted\"\n    | \"auto_approved\"\n    | \"auto_approved_blocked\"\n    | \"skipped\"\n    | \"unsupported\"\n    | \"cancelled\"\n    | \"timeout\"\n    | \"error\";\n\n/** 包装层只需要知道两件事：要不要拦、以及拦下时返回什么 */\nexport type GuardDecision =\n    | { intercept: false; status: ConfirmationStatus }\n    | {\n          intercept: true;\n          status: ConfirmationStatus;\n          result: {\n              content: Array<{ type: \"text\"; text: string }>;\n              structuredContent: Record<string, unknown>;\n          };\n      };\n\nexport type ConfirmationServer = {\n    server?: {\n        getClientCapabilities?: () => unknown;\n        elicitInput?: (params: any, options?: any) => Promise<any>;\n    };\n    cloudBaseOptions?: { envId?: string };\n    ide?: string;\n    client?: string;\n};\n\nlet warnedSkipEntries = false;\n\n/**\n * 跳过清单的合法取值：名单内的工具名，或 `工具名.action`。\n * 未知取值**显式告警但只告警一次** —— 静默忽略会让用户以为已经关掉了。\n * （不做成启动即退出：一个拼错的变量名不该让整个 MCP 服务不可用。）\n */\nfunction knownSkipNames(): Set<string> {\n    const names = new Set<string>();\n    for (const key of destructiveConfirmationKeys()) {\n        names.add(key);\n        names.add(key.slice(0, key.indexOf(\".\")));\n    }\n    return names;\n}\n\nexport function readSkipList(): string[] {\n    const entries = parseSkipList(process.env[SKIP_ENV_NAME]);\n    const known = knownSkipNames();\n    const unknown = entries.filter((entry) => !known.has(entry));\n    if (unknown.length > 0 && !warnedSkipEntries) {\n        warnedSkipEntries = true;\n        console.error(\n            `[cloudbase-mcp] ${SKIP_ENV_NAME} 含无法识别的条目，已忽略：${unknown.join(\", \")}。` +\n                `合法取值（区分大小写、无通配）：${[...known].sort().join(\", \")}`,\n        );\n    }\n    return entries;\n}\n\n/** 本次调用是否需要跳过确认 */\nexport function isSkipped(actionKey: string): boolean {\n    const toolName = actionKey.slice(0, actionKey.indexOf(\".\"));\n    return isSkippedByList(readSkipList(), toolName, actionKey);\n}\n\n/** 客户端自行应答时是否放行；取值非法时告警并回落默认（放行） */\nexport function readAutoApprovePolicy(): \"allow\" | \"block\" {\n    const raw = (process.env[AUTO_APPROVE_ENV_NAME] || \"allow\").trim().toLowerCase();\n    if (raw === \"allow\" || raw === \"block\") {\n        return raw;\n    }\n    console.error(\n        `[cloudbase-mcp] ${AUTO_APPROVE_ENV_NAME} 只接受 allow / block，收到 \"${raw}\"，按 allow 处理。`,\n    );\n    return \"allow\";\n}\n\nfunction resolveEnvId(server: ConfirmationServer): string {\n    const fromOptions = server.cloudBaseOptions?.envId;\n    if (typeof fromOptions === \"string\" && fromOptions.length > 0) {\n        return fromOptions;\n    }\n    try {\n        return getCachedEnvId() ?? t(\"confirmation.message.unknownEnv\");\n    } catch {\n        return t(\"confirmation.message.unknownEnv\");\n    }\n}\n\nfunction blockedText(\n    status: ConfirmationStatus,\n    actionKey: string,\n    targetInfo: { resource: string; envId: string },\n    params: Record<string, string | number>,\n): string {\n    const keyByStatus = {\n        cancelled: \"confirmation.blocked.cancelled\",\n        timeout: \"confirmation.blocked.timeout\",\n        error: \"confirmation.blocked.error\",\n        auto_approved_blocked: \"confirmation.blocked.autoApprovedBlocked\",\n    } as const;\n    const reasonKey = keyByStatus[status as keyof typeof keyByStatus] ?? \"confirmation.blocked.error\";\n    return [\n        t(reasonKey, params),\n        t(\"confirmation.blocked.target\", targetInfo),\n        t(\"confirmation.hint.release\", { action: actionKey }),\n        `[elicit] status=${status} executed=false`,\n    ].join(\"\\n\");\n}\n\n/**\n * 命中名单时先确认再执行。返回 `intercept: true` 表示**不要执行**，把 `result` 原样返回给客户端。\n * 任何内部异常都不能让工具调用失败：出错时按\"未执行\"处理（不同错误，也不放行）。\n */\nexport async function guardDestructiveAction(\n    server: ConfirmationServer,\n    params: { toolName: string; args: unknown; extra?: { requestId?: RequestId } },\n): Promise<GuardDecision> {\n    const resolved = resolveDestructiveAction(params.toolName, params.args);\n    if (!resolved) {\n        return { intercept: false, status: \"not_applicable\" };\n    }\n    const { key, spec } = resolved;\n\n    if (isSkipped(key)) {\n        debug(\"破坏性动作命中跳过清单，按不确认执行\", { tool: params.toolName, action: key });\n        return { intercept: false, status: \"skipped\" };\n    }\n\n    // 客户端没声明 form 能力 ⇒ 不弹、照常执行（绝不阻塞）。\n    // 能力读取本身异常时同样按\"不支持\"处理：这时候也没法弹，但绝不能因此让工具调用失败。\n    let formCapable = false;\n    try {\n        formCapable = isFormElicitationSupported(server);\n    } catch (error) {\n        debug(\"读取 elicitation 能力失败，按不支持处理\", {\n            tool: params.toolName,\n            error: error instanceof Error ? error.message : String(error),\n        });\n    }\n    if (!formCapable) {\n        return { intercept: false, status: \"unsupported\" };\n    }\n\n    const confirmLabel = t(\"confirmation.option.confirm\");\n    const cancelLabel = t(\"confirmation.option.cancel\");\n    const target = spec.target((params.args ?? {}) as Record<string, unknown>);\n    const targetInfo = {\n        resource: target.resource ?? t(\"confirmation.message.unknownResource\"),\n        envId: resolveEnvId(server),\n    };\n\n    let outcome;\n    try {\n        outcome = await requestChoiceElicitation(server, {\n            message: t(target.messageKey ?? spec.messageKey, {\n                resource: targetInfo.resource,\n                ...(typeof target.count === \"number\" ? { count: target.count } : {}),\n                envId: targetInfo.envId,\n            }),\n            field: \"confirm\",\n            // 受控选项：客户端只能回这两个值之一（不接受自由文本，见 MCP 规范 MUST NOT）\n            options: [confirmLabel, cancelLabel],\n            // 默认落在\"取消\"上：默认值就是\"不执行\"\n            defaultOption: cancelLabel,\n            timeoutMs: CONFIRMATION_TIMEOUT_MS,\n            context: {\n                toolName: params.toolName,\n                ide: server.ide,\n                client: server.client,\n                relatedRequestId: params.extra?.requestId,\n                cloudBaseOptions: server.cloudBaseOptions,\n            },\n        });\n    } catch (error) {\n        const reason = error instanceof Error ? error.message : String(error);\n        return {\n            intercept: true,\n            status: \"error\",\n            result: {\n                content: [{ type: \"text\", text: blockedText(\"error\", key, targetInfo, { reason }) }],\n                structuredContent: { status: \"error\", executed: false, tool: params.toolName },\n            },\n        };\n    }\n\n    // 表单里选了\"确认\"才算同意\n    if (outcome.status === \"accepted\" && outcome.value === confirmLabel) {\n        debug(\"破坏性动作已确认\", { tool: params.toolName, action: key, durationMs: outcome.durationMs });\n        return { intercept: false, status: \"accepted\" };\n    }\n\n    /** 拦下并给出说明；`durationMs` 只用于把\"你点的取消\"和\"自动审批被拦\"区分开 */\n    const block = (status: ConfirmationStatus, extraParams: Record<string, string | number> = {}) => ({\n        intercept: true as const,\n        status,\n        result: {\n            content: [{ type: \"text\" as const, text: blockedText(status, key, targetInfo, extraParams) }],\n            structuredContent: { status, executed: false, tool: params.toolName },\n        },\n    });\n\n    // 客户端**填了表单**却选了取消 ⇒ 按取消处理。回得再快也不改变\"它明确回了取消\"这件事。\n    if (outcome.status === \"accepted\") {\n        return block(\"cancelled\", { durationMs: outcome.durationMs, reason: \"form_returned_cancel_option\" });\n    }\n\n    // 只有\"没带内容的 decline/cancel\"才适用\"即时应答＝客户端处于不询问模式\"这条规则\n    if (outcome.status === \"declined\") {\n        const instant = outcome.durationMs < AUTO_ANSWER_THRESHOLD_MS;\n        if (instant && readAutoApprovePolicy() === \"allow\") {\n            debug(\"客户端自行应答，按未询问放行\", {\n                tool: params.toolName,\n                action: key,\n                durationMs: outcome.durationMs,\n            });\n            return { intercept: false, status: \"auto_approved\" };\n        }\n        return instant\n            ? block(\"auto_approved_blocked\", { durationMs: outcome.durationMs })\n            : block(\"cancelled\", { durationMs: outcome.durationMs, reason: outcome.reason });\n    }\n\n    if (outcome.status === \"timeout\") {\n        return block(\"timeout\", { seconds: Math.round(CONFIRMATION_TIMEOUT_MS / 1000) });\n    }\n\n    // 其余（error / 回值不在选项内 / elicitInput 不可用）一律不放行\n    return block(\"error\", { reason: outcome.reason ?? \"unknown\" });\n}\n"
    },
    {
      "path": "mcp/src/utils/credential-guard.ts",
      "content": "import { createHash } from \"node:crypto\";\nimport { t } from \"../i18n/index.js\";\nimport { AUTO_ANSWER_THRESHOLD_MS, CONFIRMATION_TIMEOUT_MS } from \"./confirmation-guard.js\";\nimport { isFormElicitationSupported, requestChoiceElicitation } from \"./elicitation.js\";\nimport { debug } from \"./logger.js\";\nimport { isSkippedByList, parseSkipList } from \"./skip-list.js\";\n\n/**\n * 凭证形态入参的**执行前软确认**（与 #1153 的破坏性确认并列，先于它执行）。\n *\n * 定位：**服务端不判凭证对错**，只在\"参数里出现凭证形态字符串\"时，要求客户端拿这串与它自己那份\n * 原始来源做一次**真实的**比对确认；确认过了才写。\n *\n * 为什么不做验签：真实 case（公开 issue #1156）里那串是**用户先粘进客户端/对话、模型再转写进参数**的，\n * 「用户原始提供的那份」服务端永远拿不到——能做比对的只有客户端。所以验签是用最难的方式解错题。\n *\n * 三条设计取舍：\n *   1. **零网络**：本模块不发任何网络请求，只做本地浅扫描 + 走既有 elicitation 通道。\n *   2. **消息里不放明文**：只给长度、分段长度、指纹（sha256 前 12 位）。这三样同样是凭证派生数据，\n *      **不得进日志/遥测**。\n *   3. **秒回一律不算\"人的核对\"**：`< AUTO_ANSWER_THRESHOLD_MS` 的应答 ⇒ 不写。⚠️ 这与 #1153\n *      的默认语义相反（那边把秒回当\"客户端替你放行\"）——凭证场景里秒回在物理上不可能包含任何\n *      人工比对动作，所以必须翻过来。\n *   4. **客户端不支持表单 elicitation ⇒ 放行**（软设计不许把普通用户整个封死；#1153 的 P0 就是\n *      栽在\"拦死\"这一类上）。\n */\n\n/** 跳过清单的环境变量名（与 #1153 的清单同形：逗号分隔、`工具名` 或 `工具名.action`、区分大小写、无通配） */\nexport const CREDENTIAL_GUARD_SKIP_ENV_NAME = \"CLOUDBASE_MCP_SKIP_CREDENTIAL_GUARD\";\n\n/** 扫描上限：只扫字符串值，避免大参数树拖慢 */\nconst MAX_DEPTH = 8;\nconst MAX_ARRAY_ITEMS = 500;\n\n/** 三段式凭证（JWT）：`header.payload.signature`，三段均为 base64url */\nconst JWT_PATTERN = /^eyJ[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$/;\n\n/** 不透明密钥形态：`cb_secret_…` / `cb_publishable_…` */\nconst OPAQUE_KEY_PATTERN = /^cb_(secret|publishable)_[A-Za-z0-9_-]+$/;\n\nexport type CredentialKind = \"jwt\" | \"opaque-key\";\n\nexport type CredentialCandidate = {\n    /** 命中的 JSON 路径（仅键名，**不含值**），用于日志定位 */\n    path: string;\n    /** 命中的字符串值（仅在本模块内部流转，绝不外泄） */\n    value: string;\n    kind: CredentialKind;\n};\n\n/** 一次调用的终态。`confirmed` 之外的都意味着\"不执行 handler\"。 */\nexport type CredentialGuardStatus =\n    | \"not_applicable\"\n    | \"skipped\"\n    | \"unsupported\"\n    | \"confirmed\"\n    | \"instant\"\n    | \"cancelled\"\n    | \"timeout\"\n    | \"error\";\n\n/** 包装层只需要知道两件事：要不要拦、以及拦下时返回什么 */\nexport type CredentialGuardDecision =\n    | { intercept: false; status: CredentialGuardStatus }\n    | {\n          intercept: true;\n          status: CredentialGuardStatus;\n          result: {\n              content: Array<{ type: \"text\"; text: string }>;\n              structuredContent: Record<string, unknown>;\n          };\n      };\n\nexport type CredentialGuardServer = {\n    server?: {\n        getClientCapabilities?: () => unknown;\n        elicitInput?: (params: any, options?: any) => Promise<any>;\n    };\n    cloudBaseOptions?: { envId?: string };\n    ide?: string;\n    client?: string;\n};\n\nfunction classify(value: string): CredentialKind | undefined {\n    if (JWT_PATTERN.test(value)) {\n        return \"jwt\";\n    }\n    if (OPAQUE_KEY_PATTERN.test(value)) {\n        return \"opaque-key\";\n    }\n    return undefined;\n}\n\n/**\n * 保守扫描参数树，返回看起来像凭证的字符串（附 JSON 路径）。\n *\n * 只扫**字符串值**；深度上限 {@link MAX_DEPTH}、每个数组上限 {@link MAX_ARRAY_ITEMS}。\n * 没有任何网络调用 —— 没扫到凭证形态字符串时后续一切照旧、零额外开销。\n */\nexport function findCredentialCandidates(args: unknown): CredentialCandidate[] {\n    const found: CredentialCandidate[] = [];\n    walk(args, \"\", 0, found);\n    return found;\n}\n\nfunction walk(node: unknown, path: string, depth: number, out: CredentialCandidate[]): void {\n    if (depth > MAX_DEPTH || node === null || node === undefined) {\n        return;\n    }\n\n    if (typeof node === \"string\") {\n        const kind = classify(node);\n        if (kind) {\n            out.push({ path, value: node, kind });\n        }\n        return;\n    }\n\n    if (typeof node !== \"object\") {\n        return;\n    }\n\n    if (Array.isArray(node)) {\n        const limit = Math.min(node.length, MAX_ARRAY_ITEMS);\n        for (let i = 0; i < limit; i += 1) {\n            walk(node[i], `${path}[${i}]`, depth + 1, out);\n        }\n        return;\n    }\n\n    for (const [key, value] of Object.entries(node as Record<string, unknown>)) {\n        walk(value, path ? `${path}.${key}` : key, depth + 1, out);\n    }\n}\n\n/**\n * 把凭证值折成可安全外发的摘要：总长度、分段长度（JWT 三段）、指纹（sha256 前 12 位十六进制）。\n *\n * ⚠️ 返回值**只能**进 elicitation 的 message（给客户端），**不得**进日志或遥测。\n */\nfunction summarize(candidate: CredentialCandidate): {\n    length: number;\n    segments: string;\n    fingerprint: string;\n} {\n    return {\n        length: candidate.value.length,\n        segments: candidate.value\n            .split(\".\")\n            .map((segment) => segment.length)\n            .join(\" / \"),\n        fingerprint: createHash(\"sha256\").update(candidate.value).digest(\"hex\").slice(0, 12),\n    };\n}\n\nfunction readSkipEntries(): string[] {\n    return parseSkipList(process.env[CREDENTIAL_GUARD_SKIP_ENV_NAME]);\n}\n\n/** 本次调用是否命中跳过清单（`工具名` 或 `工具名.action`） */\nexport function isCredentialGuardSkipped(toolName: string, actionKey?: string): boolean {\n    return isSkippedByList(readSkipEntries(), toolName, actionKey);\n}\n\nfunction actionKeyOf(toolName: string, args: unknown): string {\n    const action = (args as Record<string, unknown> | undefined)?.action;\n    return typeof action === \"string\" && action.length > 0 ? `${toolName}.${action}` : toolName;\n}\n\nfunction blockedText(\n    status: CredentialGuardStatus,\n    actionKey: string,\n    params: Record<string, string | number>,\n): string {\n    const keyByStatus = {\n        instant: \"credential.blocked.instant\",\n        cancelled: \"credential.blocked.cancelled\",\n        timeout: \"credential.blocked.timeout\",\n        error: \"credential.blocked.error\",\n    } as const;\n    const reasonKey = keyByStatus[status as keyof typeof keyByStatus] ?? \"credential.blocked.error\";\n    return [\n        t(reasonKey, params),\n        t(\"credential.hint.release\", { action: actionKey }),\n        `[credential] status=${status} executed=false`,\n    ].join(\"\\n\");\n}\n\n/**\n * 命中凭证形态时先做一次客户端核对再执行。返回 `intercept: true` 表示**不要执行**，\n * 把 `result` 原样返回给客户端。任何内部异常都不能让工具调用变成 MCP 错误。\n */\nexport async function guardCredentialWrite(\n    server: CredentialGuardServer,\n    params: { toolName: string; args: unknown; extra?: { requestId?: unknown } },\n): Promise<CredentialGuardDecision> {\n    const actionKey = actionKeyOf(params.toolName, params.args);\n\n    if (isCredentialGuardSkipped(params.toolName, actionKey)) {\n        debug(\"凭证护栏命中跳过清单，跳过核对\", { tool: params.toolName, action: actionKey });\n        return { intercept: false, status: \"skipped\" };\n    }\n\n    const candidates = findCredentialCandidates(params.args);\n    if (candidates.length === 0) {\n        return { intercept: false, status: \"not_applicable\" };\n    }\n\n    // 软设计：客户端不支持表单 elicitation 就放行（不把普通用户封死）。只记一条日志。\n    let formCapable = false;\n    try {\n        formCapable = isFormElicitationSupported(server);\n    } catch (error) {\n        debug(\"读取 elicitation 能力失败，凭证护栏按不支持处理\", {\n            tool: params.toolName,\n            error: error instanceof Error ? error.message : String(error),\n        });\n    }\n    if (!formCapable) {\n        debug(\"客户端不支持表单 elicitation，凭证核对放行\", { tool: params.toolName, action: actionKey });\n        return { intercept: false, status: \"unsupported\" };\n    }\n\n    // 只取第一处候选做摘要（消息里只给长度/分段长度/指纹三样，不放明文、不放计数）\n    const candidate = candidates[0];\n    const summary = summarize(candidate);\n    const message =\n        candidate.kind === \"jwt\"\n            ? t(\"credential.message.confirmJwt\", summary)\n            : t(\"credential.message.confirmOpaque\", { ...summary, kind: candidate.kind });\n\n    const confirmLabel = t(\"credential.option.confirm\");\n    const cancelLabel = t(\"credential.option.cancel\");\n\n    debug(\"凭证形态命中，发起写入前核对\", {\n        tool: params.toolName,\n        action: actionKey,\n        kind: candidate.kind,\n        path: candidate.path,\n        candidates: candidates.length,\n    });\n\n    let outcome;\n    try {\n        outcome = await requestChoiceElicitation(server, {\n            message,\n            field: \"confirm\",\n            options: [confirmLabel, cancelLabel],\n            // 默认落在\"取消\"上：默认值就是\"不写\"\n            defaultOption: cancelLabel,\n            timeoutMs: CONFIRMATION_TIMEOUT_MS,\n            context: {\n                toolName: params.toolName,\n                ide: server.ide,\n                client: server.client,\n                relatedRequestId: params.extra?.requestId as any,\n                cloudBaseOptions: server.cloudBaseOptions,\n            },\n        });\n    } catch (error) {\n        const reason = error instanceof Error ? error.message : String(error);\n        return {\n            intercept: true,\n            status: \"error\",\n            result: {\n                content: [{ type: \"text\", text: blockedText(\"error\", actionKey, { reason }) }],\n                structuredContent: { status: \"error\", executed: false, tool: params.toolName },\n            },\n        };\n    }\n\n    const instant = outcome.durationMs < AUTO_ANSWER_THRESHOLD_MS;\n\n    // 只有\"人真的比对过\"才算数：确认 + 非秒回\n    if (outcome.status === \"accepted\" && outcome.value === confirmLabel && !instant) {\n        debug(\"凭证核对通过，放行写入\", { tool: params.toolName, action: actionKey, durationMs: outcome.durationMs });\n        return { intercept: false, status: \"confirmed\" };\n    }\n\n    const block = (status: CredentialGuardStatus, extraParams: Record<string, string | number> = {}) => ({\n        intercept: true as const,\n        status,\n        result: {\n            content: [{ type: \"text\" as const, text: blockedText(status, actionKey, extraParams) }],\n            structuredContent: { status, executed: false, tool: params.toolName },\n        },\n    });\n\n    if (outcome.status === \"timeout\") {\n        return block(\"timeout\", { seconds: Math.round(CONFIRMATION_TIMEOUT_MS / 1000) });\n    }\n\n    if (outcome.status === \"unsupported\") {\n        // 客户端能力在核对过程中丢失：按\"不支持\"放行（软设计），而不是拦下\n        debug(\"核对过程中客户端能力不可用，凭证核对放行\", { tool: params.toolName, action: actionKey });\n        return { intercept: false, status: \"unsupported\" };\n    }\n\n    if (outcome.status === \"error\") {\n        return block(\"error\", { reason: outcome.reason ?? \"unknown\" });\n    }\n\n    // 秒回（含\"秒回同意\"）⇒ 没有任何人类参与核对 ⇒ 不写。⚠️ 与 #1153 的默认语义相反。\n    if (instant) {\n        return block(\"instant\", { durationMs: outcome.durationMs });\n    }\n\n    if (outcome.status === \"accepted\" || outcome.status === \"declined\") {\n        return block(\"cancelled\", { durationMs: outcome.durationMs });\n    }\n\n    return block(\"error\", { reason: outcome.reason ?? \"unknown\" });\n}\n"
